<?php use function Wordpresso\Core\e; ?>
<div class="page-intro"><h1>Shopping cart</h1><p>Review your products before continuing to secure checkout.</p></div>
<?php if (!empty($flash)): ?><p class="alert alert-success"><?= e($flash) ?></p><?php endif; ?><?php if (!empty($error)): ?><p class="alert alert-error"><?= e($error) ?></p><?php endif; ?>
<?php if ($items===[]): ?><div class="empty-state"><h3>Your cart is empty</h3><p>Explore the catalogue and add a plugin, theme, or plan.</p><a class="btn btn-primary" href="/store">Browse the store</a></div><?php else: ?>
<div class="cart-layout"><div class="cart-items"><?php foreach($items as $item): ?><article class="cart-item"><div class="plugin-symbol" aria-hidden="true"><?= $item['category']==='Theme'?'◫':($item['category']==='Plan'?'◈':'✦') ?></div><div class="cart-item-info"><strong><?= e($item['name']) ?></strong><span><?= e($item['category']) ?> · Qty <?= (int)$item['quantity'] ?></span></div><strong>$<?= number_format((float)$item['price']*(int)$item['quantity'],2) ?></strong><form method="post" action="/cart/remove"><?= \Wordpresso\Core\Csrf::field() ?><input type="hidden" name="product_key" value="<?= e($item['key']) ?>"><button class="remove-link" type="submit">Remove</button></form></article><?php endforeach; ?></div>
<aside class="cart-summary"><span class="section-kicker">ORDER SUMMARY</span><div><span>Subtotal</span><strong>$<?= number_format($total,2) ?> USDT</strong></div><div class="summary-total"><span>Total due</span><strong>$<?= number_format($total,2) ?> USDT</strong></div><form method="post" action="/checkout"><?= \Wordpresso\Core\Csrf::field() ?><button class="btn btn-primary btn-lg" type="submit">Continue to payment →</button></form><p>Payment is verified on BNB Smart Chain. Your access activates after verification.</p></aside></div><?php endif; ?>
